  { key: 'Check Calling Agent', name: 'Calling Agent', url: 'https://calling-agent-app.streamlit.app' },
  { key: 'Check WhatsApp Shop Assistant', name: 'WhatsApp Shop Assistant', url: 'https://whatsapp-shop-assistant.streamlit.app' },
  { key: 'Check Elumi', name: 'Elumi', url: 'https://elumi-kifayat-irfan-s-projects.vercel.app' },
];
const checkedAtPKT = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Karachi', day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false });
function checkSite(site) {
  try {
    const items = $(site.key).all();
    if (!items || items.length === 0) return { ...site, up: false, status: 'no output' };
    const j = items[0].json || {};
    if (typeof j.statusCode === 'number') {
      // 2xx = up; 3xx = up too (Streamlit Cloud answers asleep apps with a 303
      // to its auth/wake page — the host responding means the app is alive).
      const up = j.statusCode >= 200 && j.statusCode < 400;
      const extra = j.statusCode >= 300 ? ' (redirect — responding)' : '';
      return { ...site, up, status: String(j.statusCode) + extra };
    }
    const err = j.error || j.message || j.description;
    if (err) {
      const msg = typeof err === 'string' ? err : (err.message || JSON.stringify(err));
      // Axios reports non-2xx as errors like "303 - <html>...". A leading 3xx
      // means the host answered (Streamlit Cloud replies to asleep apps with
      // a 303 to its auth/wake page) — that counts as UP.
      const lead = msg.match(/^\s*(\d{3})\b/);
      if (lead) {
        const code = Number(lead[1]);
        if (code >= 300 && code < 400) return { ...site, up: true, status: lead[1] + ' (redirect — responding)' };
        return { ...site, up: false, status: lead[1] };
      }
      if (/timeout/i.test(msg)) {
        const t = msg.match(/(\d+)\s*ms/);
        return { ...site, up: false, status: t ? 'timeout (' + t[1] + 'ms)' : 'timeout' };
      }
      const m = msg.match(/\b(\d{3})\b/);
      return { ...site, up: false, status: m ? m[1] : msg.slice(0, 120) };
    }
    if (j.body !== undefined || j.data !== undefined) return { ...site, up: true, status: '200' };
    return { ...site, up: false, status: JSON.stringify(j).slice(0, 120) };
  } catch (e) {
    return { ...site, up: false, status: String((e && e.message) || e).slice(0, 120) };
  }
}
const results = sites.map(checkSite);
const down = results.filter(r => !r.up);
// Alert only after 2 consecutive failed checks. Streamlit free apps sleep when
// idle and need 30-60s to wake, so a single failure is usually a cold start.
const staticData = $getWorkflowStaticData('global');
const prevDownNames = Array.isArray(staticData.prevDown) ? staticData.prevDown : [];
const confirmedDown = down.filter(d => prevDownNames.includes(d.name));
const firstTimeDown = down.filter(d => !prevDownNames.includes(d.name)).map(d => d.name);
staticData.prevDown = down.map(d => d.name);
const message = confirmedDown.length
  ? confirmedDown.map(d => `🚨 Site down: ${d.name} (${d.url}) — status ${d.status}. Checked ${checkedAtPKT} PKT. (Down 2 checks in a row.)`).join('\n')
  : `✅ All 6 sites up. Checked ${checkedAtPKT} PKT.`;
return [{ json: { anyDown: confirmedDown.length > 0, downCount: confirmedDown.length, firstTimeDown, checkedAtPKT, message, sites: results } }];

